                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == wall:
                    sources.setdefault(color, set()).add((nr, nc))

    distances = {}
    for color, starts in sources.items():
        dist = [[-1] * w for _ in range(h)]
        q = deque()
        for r, c in starts:
            dist[r][c] = 0
            q.append((r, c))
        while q:
            r, c = q.popleft()
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if (0 <= nr < h and 0 <= nc < w and
                        grid[nr][nc] == wall and dist[nr][nc] < 0):
                    dist[nr][nc] = dist[r][c] + 1
                    q.append((nr, nc))
        distances[color] = dist

    protected = set()
    for r in range(h - 2):
        for c in range(w - 2):
            if all(grid[r + dr][c + dc] == wall
                   for dr in range(3) for dc in range(3)):
                for dr in range(3):
                    for dc in range(3):
                        if dr in (0, 2) or dc in (0, 2):
                            protected.add((r + dr, c + dc))

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != wall or (r, c) in protected:
                continue
            reached = [(dist[r][c], color)
                       for color, dist in distances.items()
                       if dist[r][c] >= 0]
            if reached:
                nearest = min(d for d, _ in reached)
                out[r][c] = max(color for d, color in reached if d == nearest)
    return out
